          fluidRow(
            actionButton(ns('previous_tab_5'), label = "Previous"),
            actionButton(ns('next_tab_5'), label = "Next")
          )
        ),
        target = 'tab4',
        position = 'after'
      )
      updateTabsetPanel(
        session, 'mainTabSet',
                selected = 'tab4'
      )
    })
    observeEvent(input$previous_tab_6, {
      delay(50, {
